/**
 * Title: Koi Pond (WebGL)
 * Description: A serene pond viewed from above. Shader-rendered koi with
 *   orange-and-cream patch patterns glide on smooth wander paths, tails
 *   wiggling with their speed, casting soft shadows on the pond bed.
 *   Caustic light webs dance across the water and refraction gently warps
 *   everything below the surface. Move your mouse near a koi and it will
 *   curiously follow; click the water to cast an expanding ripple ring that
 *   startles nearby fish into a quick dart. Occasionally a koi kisses the
 *   surface, leaving a small ambient dimple.
 *
 *   Showcases: WebGL SDF creatures, uniform-driven simulation, click ripples
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FISH_COUNT       = 3;      // number of koi (shader is rebuilt from this)
const FISH_SIZE        = 0.055;  // koi half-length in scene units
const FISH_SPEED       = 0.07;   // cruise speed (scene units per second)
const MAX_RIPPLES      = 8;      // simultaneous ripple rings
const RIPPLE_SPEED     = 0.22;   // ripple expansion rate
const CAUSTIC_STRENGTH = 0.45;   // brightness of caustic light webs
const MOUSE_LURE_RANGE = 0.55;   // how close the cursor must be to attract a koi
const SCARE_FORCE      = 0.38;   // dart impulse when clicking near fish
/* ──────────────────────────────────────────── */

var canvas, gl, program;
var uTime, uRes, uFish, uRipples;
var w = 0, h = 0, aspect = 1.6;
var t0 = 0, lastT = 0;
var mouse = { x: -9, y: -9, last: -999 };
var fish = [];
var ripples = [];
var fishData = new Float32Array(FISH_COUNT * 4);
var rippleData = new Float32Array(MAX_RIPPLES * 3);
var nextDimple = 0;

setInterval(function () { self.postMessage({ type: 'heartbeat' }); }, 1000);

var VERT = 'attribute vec2 a_pos;void main(){gl_Position=vec4(a_pos,0.0,1.0);}';

var FRAG = [
	'precision highp float;',
	'uniform float u_time;',
	'uniform vec2 u_res;',
	'uniform vec4 u_fish[' + FISH_COUNT + '];',
	'uniform vec3 u_ripples[' + MAX_RIPPLES + '];',
	'',
	'const float FL = ' + FISH_SIZE.toFixed(4) + ';',
	'',
	'float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}',
	'float noise(vec2 p){',
	'  vec2 i=floor(p),f=fract(p);',
	'  f=f*f*(3.0-2.0*f);',
	'  return mix(mix(hash(i),hash(i+vec2(1.0,0.0)),f.x),',
	'             mix(hash(i+vec2(0.0,1.0)),hash(i+vec2(1.0,1.0)),f.x),f.y);',
	'}',
	'float fbm(vec2 p){',
	'  float v=0.0,a=0.5;',
	'  for(int i=0;i<5;i++){v+=a*noise(p);p=mat2(1.6,1.2,-1.2,1.6)*p;a*=0.5;}',
	'  return v;',
	'}',
	'',
	'float caustic(vec2 p, float t){',
	'  float n1 = fbm(p*4.0 + vec2(t*0.10, t*0.06));',
	'  float n2 = fbm(p*4.0 + vec2(-t*0.07, t*0.09) + 4.7);',
	'  float c1 = pow(0.5 + 0.5*sin(n1*14.0 + t*0.6), 5.0);',
	'  float c2 = pow(0.5 + 0.5*sin(n2*14.0 - t*0.5), 5.0);',
	'  return min(c1*c2*3.0, 1.0);',
	'}',
	'',
	'vec2 rippleWarp(vec2 p, out float glow){',
	'  vec2 off = vec2(0.0);',
	'  glow = 0.0;',
	'  for (int i = 0; i < ' + MAX_RIPPLES + '; i++){',
	'    vec3 rp = u_ripples[i];',
	'    float act = step(0.0, rp.z);',
	'    vec2 d = p - rp.xy;',
	'    float dist = length(d) + 0.0001;',
	'    float rad = rp.z * ' + RIPPLE_SPEED.toFixed(3) + ';',
	'    float band = exp(-pow((dist - rad)*26.0, 2.0));',
	'    float dec = exp(-rp.z*1.4) * act;',
	'    off += (d/dist) * band * dec * 0.012;',
	'    glow += band * dec;',
	'  }',
	'  return p + off;',
	'}',
	'',
	'float fishBody(vec2 p, vec4 f, out vec2 lc){',
	'  vec2 d = p - f.xy;',
	'  float ca = cos(f.z), sa = sin(f.z);',
	'  vec2 l = vec2(ca*d.x + sa*d.y, -sa*d.x + ca*d.y);',
	'  float s = l.x / FL;',
	'  lc = vec2(s, l.y / FL);',
	'  if (s > 1.15 || s < -1.7 || abs(l.y) > FL*0.8) return 0.0;',
	'  float wig = sin(s*3.2 - f.w) * FL * 0.20 * (0.55 - 0.4*clamp(s, -1.0, 1.0));',
	'  float ly = abs(l.y - wig);',
	'  float e = 2.5 / u_res.y;',
	'  float bw = FL*0.36*sqrt(max(0.0, 1.0 - s*s)) * (0.62 + 0.38*smoothstep(-1.0, 0.4, s));',
	'  float body = smoothstep(bw + e, bw - e, ly) * smoothstep(1.02, 0.96, abs(s));',
	'  float ft = clamp((-s - 0.85)/0.7, 0.0, 1.0);',
	'  float tw = FL*0.30*ft;',
	'  float fin = smoothstep(tw + e, tw - e, ly) * step(0.02, ft) * smoothstep(1.6, 1.5, -s);',
	'  return max(body, fin*0.85);',
	'}',
	'',
	'void main(){',
	'  float t = u_time;',
	'  vec2 p = gl_FragCoord.xy / u_res.y;',
	'  float glow;',
	'  vec2 q = rippleWarp(p, glow);',
	'  vec2 wob = (vec2(noise(q*6.0 + t*0.25), noise(q*6.0 + 13.7 + t*0.22)) - 0.5) * 0.012;',
	'  vec2 wq = q + wob;',
	'',
	'  float depth = fbm(wq*2.2 + 3.1);',
	'  vec3 col = mix(vec3(0.012,0.075,0.085), vec3(0.035,0.16,0.15), depth);',
	'  col += vec3(0.02,0.05,0.05) * fbm(wq*5.0 - t*0.02);',
	'',
	'  vec2 lc;',
	'  for (int i = 0; i < ' + FISH_COUNT + '; i++){',
	'    vec4 f = u_fish[i];',
	'    float seed = float(i)*7.31;',
	'    float shA = fishBody(wq + vec2(0.013, -0.013), f, lc);',
	'    col = mix(col, col*0.45, shA*0.55);',
	'    float a = fishBody(wq, f, lc);',
	'    if (a > 0.003){',
	'      float patch = noise(lc*vec2(2.2, 5.5) + seed);',
	'      vec3 fc = mix(vec3(0.93,0.90,0.84), vec3(0.98,0.45,0.10), smoothstep(0.46,0.56,patch));',
	'      fc *= 0.82 + 0.28*noise(lc*vec2(6.0,9.0) + seed*1.7);',
	'      fc *= 0.85 + 0.15*smoothstep(-1.0, 1.0, lc.x);',
	'      col = mix(col, fc, a*0.92);',
	'    }',
	'  }',
	'',
	'  float ca = caustic(wq, t);',
	'  col += vec3(0.30,0.50,0.45) * ca * ' + CAUSTIC_STRENGTH.toFixed(3) + ';',
	'  col += vec3(0.50,0.75,0.70) * glow * 0.25;',
	'',
	'  vec2 vp = p - vec2(u_res.x/u_res.y*0.5, 0.5);',
	'  col *= 1.0 - dot(vp, vp)*0.5;',
	'  gl_FragColor = vec4(col, 1.0);',
	'}'
].join('\n');

function compile(type, src) {
	var s = gl.createShader(type);
	gl.shaderSource(s, src);
	gl.compileShader(s);
	if (!gl.getShaderParameter(s, gl.COMPILE_STATUS))
		throw new Error(gl.getShaderInfoLog(s));
	return s;
}

function initGL() {
	var vs = compile(gl.VERTEX_SHADER, VERT);
	var fs = compile(gl.FRAGMENT_SHADER, FRAG);
	program = gl.createProgram();
	gl.attachShader(program, vs);
	gl.attachShader(program, fs);
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS))
		throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	var buf = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buf);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	var a = gl.getAttribLocation(program, 'a_pos');
	gl.enableVertexAttribArray(a);
	gl.vertexAttribPointer(a, 2, gl.FLOAT, false, 0, 0);
	uTime = gl.getUniformLocation(program, 'u_time');
	uRes = gl.getUniformLocation(program, 'u_res');
	uFish = gl.getUniformLocation(program, 'u_fish[0]');
	uRipples = gl.getUniformLocation(program, 'u_ripples[0]');
	t0 = performance.now() / 1000;
}

function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

function pickWaypoint(f) {
	f.wx = 0.12 + Math.random() * (aspect - 0.24);
	f.wy = 0.12 + Math.random() * 0.76;
}

function initFish() {
	fish = [];
	for (var i = 0; i < FISH_COUNT; i++) {
		var f = {
			x: 0.2 + Math.random() * (aspect - 0.4),
			y: 0.15 + Math.random() * 0.7,
			vx: 0.02, vy: 0.0,
			phase: Math.random() * 6.28,
			wx: 0, wy: 0
		};
		pickWaypoint(f);
		fish.push(f);
	}
}

function initRipples() {
	ripples = [];
	for (var i = 0; i < MAX_RIPPLES; i++) ripples.push({ x: 0, y: 0, age: -1 });
	for (var j = 0; j < MAX_RIPPLES * 3; j++) rippleData[j] = -1;
}

function addRipple(x, y) {
	var oldest = 0, oldestAge = -2;
	for (var i = 0; i < MAX_RIPPLES; i++) {
		if (ripples[i].age < 0) { oldest = i; break; }
		if (ripples[i].age > oldestAge) { oldestAge = ripples[i].age; oldest = i; }
	}
	ripples[oldest].x = x;
	ripples[oldest].y = y;
	ripples[oldest].age = 0;
}

function scare(x, y) {
	for (var i = 0; i < FISH_COUNT; i++) {
		var f = fish[i];
		var dx = f.x - x, dy = f.y - y;
		var d = Math.sqrt(dx * dx + dy * dy) || 0.0001;
		var imp = SCARE_FORCE * Math.exp(-d * 4.0);
		f.vx += dx / d * imp;
		f.vy += dy / d * imp;
	}
}

function updateFish(dt, now) {
	for (var i = 0; i < FISH_COUNT; i++) {
		var f = fish[i];
		var tx = f.wx, ty = f.wy;
		if (now - mouse.last < 3.0) {
			var mdx = mouse.x - f.x, mdy = mouse.y - f.y;
			var md = Math.sqrt(mdx * mdx + mdy * mdy);
			if (md < MOUSE_LURE_RANGE && md > 0.13) { tx = mouse.x; ty = mouse.y; }
		}
		var dx = tx - f.x, dy = ty - f.y;
		var d = Math.sqrt(dx * dx + dy * dy) || 0.0001;
		if (d < 0.06) pickWaypoint(f);
		var sp = FISH_SPEED * (0.8 + 0.4 * Math.sin(f.phase * 0.13 + i * 2.1));
		var k = Math.min(1, dt * 1.2);
		f.vx += (dx / d * sp - f.vx) * k;
		f.vy += (dy / d * sp - f.vy) * k;
		f.x = clamp(f.x + f.vx * dt, 0.05, aspect - 0.05);
		f.y = clamp(f.y + f.vy * dt, 0.06, 0.94);
		var spd = Math.sqrt(f.vx * f.vx + f.vy * f.vy);
		f.phase += dt * (3.0 + spd * 45.0);
		fishData[i * 4] = f.x;
		fishData[i * 4 + 1] = f.y;
		fishData[i * 4 + 2] = Math.atan2(f.vy, f.vx);
		fishData[i * 4 + 3] = f.phase;
	}
}

function updateRipples(dt) {
	for (var i = 0; i < MAX_RIPPLES; i++) {
		var r = ripples[i];
		if (r.age >= 0) {
			r.age += dt;
			if (r.age > 3.2) r.age = -1;
		}
		rippleData[i * 3] = r.x;
		rippleData[i * 3 + 1] = r.y;
		rippleData[i * 3 + 2] = r.age;
	}
}

function render() {
	var now = performance.now() / 1000;
	var dt = lastT ? Math.min(now - lastT, 0.1) : 0.016;
	lastT = now;
	updateFish(dt, now);
	updateRipples(dt);
	if (now > nextDimple) {
		var f = fish[Math.floor(Math.random() * FISH_COUNT)];
		addRipple(f.x, f.y);
		nextDimple = now + 5 + Math.random() * 9;
	}
	gl.viewport(0, 0, w, h);
	gl.uniform1f(uTime, now - t0);
	gl.uniform2f(uRes, w, h);
	gl.uniform4fv(uFish, fishData);
	gl.uniform3fv(uRipples, rippleData);
	gl.drawArrays(gl.TRIANGLES, 0, 3);
	requestAnimationFrame(render);
}

function sceneX(px) { return px / h; }
function sceneY(py) { return 1.0 - py / h; }

self.onmessage = function (e) {
	switch (e.data.type) {
		case 'init':
			canvas = e.data.canvas;
			w = e.data.width; h = e.data.height;
			canvas.width = w; canvas.height = h;
			aspect = w / h;
			gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
			if (!gl) {
				var c2 = canvas.getContext('2d');
				if (c2) {
					c2.fillStyle = '#04141a';
					c2.fillRect(0, 0, w, h);
					c2.fillStyle = '#ff4466';
					c2.font = '16px monospace';
					c2.textAlign = 'center';
					c2.fillText('WebGL not available', w / 2, h / 2);
				}
				return;
			}
			try {
				initGL();
				initFish();
				initRipples();
				nextDimple = performance.now() / 1000 + 4;
				render();
			} catch (err) {
				self.postMessage({ type: 'error', message: 'Koi Pond shader: ' + err.message });
			}
			break;

		case 'resize':
			w = e.data.width; h = e.data.height;
			canvas.width = w; canvas.height = h;
			aspect = w / h;
			break;

		case 'mousemove':
			mouse.x = sceneX(e.data.x);
			mouse.y = sceneY(e.data.y);
			mouse.last = performance.now() / 1000;
			break;

		case 'click':
			var cx = sceneX(e.data.x), cy = sceneY(e.data.y);
			addRipple(cx, cy);
			scare(cx, cy);
			break;
	}
};

